import Foundation

/// Native validation of service-free preparation identity and metadata; lexical policy stays in the compiler.
struct ManagedPortablePreparation: Sendable {
    /// Existing SDK preparation value, preserving public type and receipt inputs.
    let source: ManagedSketchPreprocessor.Source

    /// Requires exact captured request/source identity, closed fields and bounded generated bytes.
    @concurrent static func decode(_ json: String, request: ManagedPortableRequest) async throws -> Self {
        try Task.checkCancellation()
        let root = try WireJSON.parse(Data(json.utf8), maximumBytes: 2_000_000, maximumTokens: 4096)
        guard try root.required("schema").uint32() == 1,
              try root.required("operation").string() == "prepare",
              try root.required("buildID").string() == request.buildID,
              try root.required("requestSHA256").string() == request.requestSHA256 else { throw WireJSON.invalid }
        let outcome = try root.required("outcome").string()
        if outcome != "succeeded" {
            try fields(root, ["schema", "operation", "buildID", "requestSHA256", "outcome", "error", "diagnostics"])
            let error = try root.required("error"); try fields(error, ["code", "stage", "message"])
            let code = try error.required("code").string(), message = try error.required("message").string()
            guard try error.required("stage").string() == "preprocessing", message.utf8.count <= 4096,
                  !message.contains("\0"), !code.isEmpty, code.utf8.count <= 64,
                  code.utf8.allSatisfy({ $0 == 95 || (97...122).contains($0) }),
                  outcome == (code == "cancelled" ? "cancelled" : code == "timed_out" ? "timed_out" : "failed") else { throw WireJSON.invalid }
            let diagnostics = try ManagedPortableOutput.diagnosticRecords(root.required("diagnostics"))
            switch code {
            case "unsupported_source": throw SketchBuildError.unsupportedSource(diagnostics)
            case "invalid_source": throw SketchBuildError.invalidInput(message)
            case "cancelled": throw CancellationError()
            case "timed_out": throw ManagedCompilerError.timedOut
            default: throw ManagedCompilerError.runtime("Source preparation failed: " + code)
            }
        }
        try fields(root, ["schema", "operation", "buildID", "requestSHA256", "outcome", "preparation"])
        let result = try root.required("preparation")
        try fields(result, ["sourceSHA256", "translationUnit", "translationUnitSHA256", "requestSHA256", "sourceLineCount", "sourceBOMBytes"])
        let unit = try result.required("translationUnit").string()
        let originalHash = NanoManagedContract.digest(Data(request.snapshot.source.utf8)), unitHash = NanoManagedContract.digest(Data(unit.utf8))
        let lines = try result.required("sourceLineCount").uint32(), bom = try result.required("sourceBOMBytes").uint32()
        guard try result.required("requestSHA256").string() == request.requestSHA256,
              try result.required("sourceSHA256").string() == originalHash,
              try result.required("translationUnitSHA256").string() == unitHash,
              lines >= 1, lines <= request.snapshot.source.utf8.count + 1,
              bom == (request.snapshot.source.hasPrefix("\u{feff}") ? 3 : 0),
              unit.utf8.count <= 262400, unit.hasPrefix("#include <Arduino.h>\n#line 1 \"" + request.snapshot.filename + "\"\n"),
              unit.hasSuffix("\n") else { throw WireJSON.invalid }
        try Task.checkCancellation()
        return Self(source: ManagedSketchPreprocessor.Source(sourceSHA256: originalHash, translationUnit: unit,
            translationUnitSHA256: unitHash, sourceLineCount: Int(lines)))
    }
    /// Rejects additive/unknown fields before translating portable data into SDK types.
    private static func fields(_ value: WireJSON.Value, _ names: [String]) throws {
        guard Set(try value.object().keys) == Set(names.map { Data($0.utf8) }) else { throw WireJSON.invalid }
    }
}
